def _load_bundle():
    raw=zlib.decompress(base64.b85decode(EMBEDDED_ZERO_BUNDLE_B85.encode("ascii")))
    assert hashlib.sha256(raw).hexdigest()==EMBEDDED_ZERO_BUNDLE_SHA256
    return json.loads(raw.decode("utf-8"))

def _trim(p):
    p=list(p)
    while len(p)>1 and p[-1]==0: p.pop()
    return p
def _der(p): return [F(i)*p[i] for i in range(1,len(p))] or [F(0)]
def _divrem(a,b):
    a=_trim(a); b=_trim(b); r=a[:]
    q=[F(0)]*max(1,len(a)-len(b)+1)
    while len(r)>=len(b) and not (len(r)==1 and r[0]==0):
        c=r[-1]/b[-1]; d=len(r)-len(b); q[d]+=c
        for i in range(len(b)): r[d+i]-=c*b[i]
        r=_trim(r)
    return _trim(q),_trim(r)
def _eval(p,x):
    s=F(0)
    for c in reversed(p): s=s*x+c
    return s
def _sturm(p):
    seq=[_trim(p),_der(_trim(p))]
    while True:
        _,r=_divrem(seq[-2],seq[-1])
        if len(r)==1 and r[0]==0: break
        seq.append([-x for x in r])
    return seq
def _var(vals):
    s=[1 if v>0 else -1 for v in vals if v]
    return sum(s[i]!=s[i-1] for i in range(1,len(s)))
def _padd(p,q):
    n=max(len(p),len(q)); out=[F(0)]*n
    for i in range(n):
        out[i]=(p[i] if i<len(p) else 0)+(q[i] if i<len(q) else 0)
    return _trim(out)
def _pscale(p,s): return [s*x for x in p]
def _px(p): return [F(0)]+list(p)
def _Tpoly(n):
    if n==0:return [F(1)]
    if n==1:return [F(0),F(1)]
    a,b=[F(1)],[F(0),F(1)]
    for _ in range(1,n):
        a,b=b,_padd(_pscale(_px(b),2),_pscale(a,-1))
    return b

MS=[1,3,5,7,9,11,13,15]
B=F(31831,25000)
E0=F(1,500)
SQRT2_LO=F("1.414213562373095")
SQRT2_HI=F("1.414213562373096")
assert SQRT2_LO*SQRT2_LO<2<SQRT2_HI*SQRT2_HI

AHAT=[F("1.2584137712886"),F("-0.3937596567200"),F("0.2124600498986"),
      F("-0.1306671899250"),F("0.0830167154073"),F("-0.0515205674305"),
      F("0.0291722779340"),F("-0.0126226703866")]
MBAR=F("1.00000000000008")
QWIT=sum((a/MBAR)**2 for a in AHAT)

SPECIAL=["0.295476559577","0.435611372980","0.609921213422","0.735129635279",
         "0.852489066616","0.931563097051","0.983213205237"]
YFRACS=sorted(set([F(j,256) for j in range(257)]+[F(s) for s in SPECIAL]))
YQ=[F("0.295476559577"),F("0.609921213422"),F("0.852489066616"),F("0.983213205237")]

def trow(y):
    T=[F(0)]*16; T[0]=1; T[1]=y
    for n in range(1,15): T[n+1]=2*y*T[n]-T[n-1]
    return [T[m] for m in MS]

BASE=[]; BB=[]
for y in YFRACS:
    r=trow(y); BASE.append(r); BB.append(F(1)); BASE.append([-x for x in r]); BB.append(F(1))
EROW=[sum(trow(y)[r] for y in YQ) for r in range(8)]

def root_box(oid):
    signs=[1 if ((oid>>bit)&1) else -1 for bit in range(6,-1,-1)]
    l=[F(0)]*8;u=[F(0)]*8;l[0]=0;u[0]=B
    for r,s in enumerate(signs,1):
        if s>0:l[r]=0;u[r]=B
        else:l[r]=-B;u[r]=0
    return l,u

def apply_path(l,u,path,internals,oid):
    p=""
    for ch in path:
        rr=internals[f"{oid}:{p}"]
        mid=(l[rr]+u[rr])/2
        if ch=="0":u=u[:];u[rr]=mid
        else:l=l[:];l[rr]=mid
        p+=ch
    return l,u

def rows(l,u,mode):
    A=list(BASE);b=list(BB)
    if mode=="exterior":A.append(EROW);b.append(F(4)-E0)
    else:A.append([-x for x in EROW]);b.append(-(F(4)-E0))
    for r in range(8):
        q=[F(0)]*8;q[r]=1;A.append(q);b.append(u[r])
        q=[F(0)]*8;q[r]=-1;A.append(q);b.append(-l[r])
    return A,b

def secant(l,u):
    return [l[r]+u[r] for r in range(8)],-sum(l[r]*u[r] for r in range(8))

def verify_cert(cert,A,b,c=None,const=None):
    supp=cert["support"];w=[F(x) for x in cert["weights"]]
    assert all(x>=0 for x in w)
    if cert["type"] in ("BOUND","PRUNE"):
        assert c is not None
        for r in range(8):
            assert sum(A[supp[j]][r]*w[j] for j in range(len(w)))==c[r]
        val=const+sum(b[supp[j]]*w[j] for j in range(len(w)))
        assert val==F(cert["value"])
        return val
    assert cert["type"]=="EMPTY"
    for r in range(8):
        assert sum(A[supp[j]][r]*w[j] for j in range(len(w)))==0
    val=sum(b[supp[j]]*w[j] for j in range(len(w)))
    assert val==F(cert["value"]) and val<0
    return val

def run_zero_band_sturm():
    P=[F(0)]
    for a,n in zip(AHAT,MS): P=_padd(P,_pscale(_Tpoly(n),a))
    P2=[F(0)]*(2*len(P)-1)
    for i,a in enumerate(P):
        for j,b in enumerate(P):P2[i+j]+=a*b
    Q=[-x for x in P2];Q[0]+=MBAR*MBAR
    S=_sturm(Q)
    vm=_var([_eval(q,F(-1)) for q in S]);vp=_var([_eval(q,F(1)) for q in S])
    assert vm==vp and _eval(Q,F(-1))>0 and _eval(Q,F(1))>0
    print("PASS_ZERO_BAND_RATIONAL_STURM_WITNESS")
    print("certified norm <",float(MBAR))

def run_zero_global_exact():
    bundle=_load_bundle()
    ld=bundle["local"]; ed=bundle["exterior"]; refined=bundle["refined"]
    local_worst=None; local_counts={"BOUND":0,"EMPTY":0}
    for key,cert in ld["leaves"].items():
        oid_s,path=key.split(":");oid=int(oid_s)
        l,u=root_box(oid);l,u=apply_path(l,u,path,ld["internals"],oid)
        A,b=rows(l,u,"local");c,const=secant(l,u)
        val=verify_cert(cert,A,b,c,const)
        local_counts[cert["type"]]+=1
        if cert["type"]=="BOUND" and (local_worst is None or val>local_worst):local_worst=val
    assert local_worst is not None

    ext_worst=None;ext_counts={"BOUND":0,"EMPTY":0}
    # Exact base leaves
    for key,cert in ed["leaves"].items():
        oid_s,path=key.split(":");oid=int(oid_s)
        l,u=root_box(oid);l,u=apply_path(l,u,path,ed["internals"],oid)
        A,b=rows(l,u,"exterior");c,const=secant(l,u)
        val=verify_cert(cert,A,b,c,const)
        ext_counts[cert["type"]]+=1
        if cert["type"]=="BOUND" and (ext_worst is None or val>ext_worst):ext_worst=val
    # 52 refined replacements
    assert set(bundle["failed_boxes"])==set(refined["root_keys"])
    for rootkey,box in bundle["failed_boxes"].items():
        l=[F(s) for s in box["l"]];u=[F(s) for s in box["u"]]
        cert=refined["leaves"][rootkey+"R"]
        A,b=rows(l,u,"exterior");c,const=secant(l,u)
        val=verify_cert(cert,A,b,c,const)
        ext_counts[cert["type"]]+=1
        if cert["type"]=="BOUND" and (ext_worst is None or val>ext_worst):ext_worst=val

    assert local_counts=={"BOUND":264,"EMPTY":258}
    assert ext_counts=={"BOUND":2208,"EMPTY":2654}
    assert ext_worst<QWIT
    B_lower=SQRT2_LO*QWIT
    B_upper=SQRT2_HI*local_worst
    assert B_lower<B_upper
    print("PASS_DEGREE15_ZERO_BAND_GLOBAL_BRACKET_EXACT")
    print("LOCAL counts =",local_counts,"worst q upper =",float(local_worst))
    print("EXTERIOR counts =",ext_counts,"worst q upper =",float(ext_worst))
    print("rigorous Bell lower >",float(B_lower))
    print("rigorous Bell upper <",float(B_upper))
    print("rigorous bracket width <",float(B_upper-B_lower))
    print("embedded bundle SHA256 =",EMBEDDED_ZERO_BUNDLE_SHA256)
    return float(B_lower),float(B_upper)


def run_krawczyk_isolation():
    import mpmath as mp
    mp.mp.dps=70; iv=mp.iv
    ms=[1,3,5,7,9,11,13,15]
    yc=[mp.mpf('0.295476559577023008116035083643294585772774282782331056518516'),mp.mpf('0.609921213422221442178833055020356872222976362491008850210796'),mp.mpf('0.852489066616376811110042845754734775771441661324236973099079'),mp.mpf('0.983213205237062045577120864898055139974953611263286360397747')]
    ac=[mp.mpf('1.258413771288607'),mp.mpf('-0.393759656720011'),mp.mpf('0.212460049898647'),mp.mpf('-0.130667189924970'),mp.mpf('0.083016715407268'),mp.mpf('-0.051520567430526'),mp.mpf('0.029172277934015'),mp.mpf('-0.012622670386635')]
    # refine exact center a/lambda from y
    V=mp.matrix([[mp.chebyt(n,y) for n in ms] for y in yc]);D=mp.matrix([[n*mp.chebyu(n-1,y) for n in ms] for y in yc]);lam=mp.lu_solve(V*V.T,mp.matrix([1]*4));a=V.T*lam
    ac=[a[i] for i in range(8)];lc=[lam[i] for i in range(4)]
    def Tpp(n,x): return (x*n*mp.chebyu(n-1,x)-n*n*mp.chebyt(n,x))/(1-x*x)
    # center F/J
    def center_FJ():
     E=mp.matrix([[Tpp(n,y) for n in ms] for y in yc]);F=mp.matrix(16,1);J=mp.matrix(16,16)
     # zero init
     for i in range(16):
      for j in range(16):J[i,j]=0
     for i in range(4):
      F[i]=(V[i,:]*a)[0]-1;F[4+i]=(D[i,:]*a)[0]
      for k in range(8):J[i,k]=V[i,k];J[4+i,k]=D[i,k]
      J[i,12+i]=(D[i,:]*a)[0];J[4+i,12+i]=(E[i,:]*a)[0]
     for k in range(8):
      F[8+k]=a[k]-sum(V[j,k]*lam[j] for j in range(4));J[8+k,k]=1
      for j in range(4):J[8+k,8+j]=-V[j,k];J[8+k,12+j]=-lam[j]*D[j,k]
     return F,J
    F0,J0=center_FJ();C=J0**-1
    print('F norm',mp.norm(F0,mp.inf),'C norm',mp.norm(C,mp.inf))
    def interval_J(ra,rl,ry):
     A=[iv.mpf([ac[i]-ra,ac[i]+ra]) for i in range(8)];L=[iv.mpf([lc[i]-rl,lc[i]+rl]) for i in range(4)];Y=[iv.mpf([yc[i]-ry,yc[i]+ry]) for i in range(4)]
     Vi=iv.matrix(4,8);Di=iv.matrix(4,8);Ei=iv.matrix(4,8)
     for i in range(4):
      for k,n in enumerate(ms):
       Vi[i,k]=iv.chebyt(n,Y[i]);Di[i,k]=n*iv.chebyu(n-1,Y[i]);Ei[i,k]=(Y[i]*Di[i,k]-n*n*Vi[i,k])/(1-Y[i]*Y[i])
     Ji=iv.matrix(16,16)
     for i in range(16):
      for j in range(16):Ji[i,j]=iv.mpf([0,0])
     for i in range(4):
      for k in range(8):Ji[i,k]=Vi[i,k];Ji[4+i,k]=Di[i,k]
      Ji[i,12+i]=sum(Di[i,k]*A[k] for k in range(8));Ji[4+i,12+i]=sum(Ei[i,k]*A[k] for k in range(8))
     for k in range(8):
      Ji[8+k,k]=1
      for j in range(4):Ji[8+k,8+j]=-Vi[j,k];Ji[8+k,12+j]=-L[j]*Di[j,k]
     return Ji
    # Publication isolation box: common radius 1e-9 in all 16 variables.
    ra=rl=ry=mp.mpf('1e-9')
    JI=interval_J(ra,rl,ry)
    rads=[ra]*16
    rat=[]
    for i in range(16):
        rr=abs(sum(C[i,k]*F0[k] for k in range(16)))
        for j in range(16):
            z=iv.mpf([int(i==j),int(i==j)])
            for k in range(16):
                z-=iv.mpf([C[i,k],C[i,k]])*JI[k,j]
            lo=mp.mpf(z.a);hi=mp.mpf(z.b)
            rr+=max(abs(lo),abs(hi))*rads[j]
        rat.append(rr/rads[i])
    print('PASS_ZERO_BAND_KKT16_KRAWCZYK_LOCAL_UNIQUENESS')
    print('radius =',ra)
    print('max Krawczyk radius ratio =',max(rat))
    print('coefficient group max =',max(rat[:8]))
    print('lambda group max =',max(rat[8:12]))
    print('contact group max =',max(rat[12:]))
    assert max(rat) < 1

def main():
    run_zero_band_sturm()
    lower,upper=run_zero_global_exact()
    run_krawczyk_isolation()
    assert lower < 2.56173695411067 < upper
    print("PASS_GITHUB_TEST_02_ZERO_BANDWIDTH_GLOBAL")

def test_all_zero_bandwidth():
    main()

if __name__=="__main__":
    main()
